-- Safe, repeatable forum and administration schema. Run in Supabase SQL Editor.
create extension if not exists pgcrypto;
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, username text not null check(char_length(username) between 2 and 32), email text not null, role text not null default 'member' check(role in ('member','superadmin','admin')), created_at timestamptz not null default now());
alter table public.profiles add column if not exists email text; alter table public.profiles drop constraint if exists profiles_role_check; alter table public.profiles add constraint profiles_role_check check(role in ('member','superadmin','admin'));
create table if not exists public.registration_audit (user_id uuid primary key references public.profiles(id) on delete cascade, province text, device_name text, consented_at timestamptz not null default now());
create table if not exists public.posts (id uuid primary key default gen_random_uuid(), author_id uuid not null references public.profiles(id) on delete cascade, body text not null check(char_length(body) between 1 and 5000), official boolean not null default false, created_at timestamptz not null default now());
create table if not exists public.post_media (id uuid primary key default gen_random_uuid(), post_id uuid not null references public.posts(id) on delete cascade, path text not null unique, mime_type text not null, created_at timestamptz not null default now());
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,username,email,role) values(new.id,coalesce(nullif(new.raw_user_meta_data->>'username',''),split_part(new.email,'@',1)),new.email,case when new.email='3538882915@qq.com' then 'admin' else 'member' end) on conflict(id) do update set username=excluded.username,email=excluded.email; return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users; create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
insert into public.profiles(id,username,email,role) select id,coalesce(nullif(raw_user_meta_data->>'username',''),split_part(email,'@',1)),email,case when email='3538882915@qq.com' then 'admin' else 'member' end from auth.users on conflict(id) do update set username=excluded.username,email=excluded.email,role=excluded.role;
create or replace function public.is_primary_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role='admin'); $$;
create or replace function public.can_moderate() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role in ('admin','superadmin')); $$;
grant usage on schema public to anon,authenticated; grant select on public.posts,public.post_media to anon,authenticated; grant select,insert,update,delete on public.profiles,public.posts,public.post_media to authenticated;
alter table public.profiles enable row level security; alter table public.registration_audit enable row level security; alter table public.posts enable row level security; alter table public.post_media enable row level security;
drop policy if exists "profiles own read" on public.profiles; drop policy if exists "profiles own update" on public.profiles; drop policy if exists "posts visible" on public.posts; drop policy if exists "post insert" on public.posts; drop policy if exists "post delete" on public.posts; drop policy if exists "post update" on public.posts; drop policy if exists "media visible" on public.post_media; drop policy if exists "media insert" on public.post_media; drop policy if exists "media delete" on public.post_media;
create policy "profiles own read" on public.profiles for select to authenticated using(id=auth.uid()); create policy "profiles own update" on public.profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid() and role=(select role from public.profiles where id=auth.uid()));
create policy "posts visible" on public.posts for select using(true); create policy "post insert" on public.posts for insert to authenticated with check(author_id=auth.uid() and (not official or public.can_moderate())); create policy "post delete" on public.posts for delete to authenticated using(author_id=auth.uid() or public.can_moderate()); create policy "post update" on public.posts for update to authenticated using(author_id=auth.uid() or public.can_moderate()) with check(author_id=auth.uid() or public.can_moderate());
create policy "media visible" on public.post_media for select using(true); create policy "media insert" on public.post_media for insert to authenticated with check(exists(select 1 from public.posts where id=post_id and author_id=auth.uid())); create policy "media delete" on public.post_media for delete to authenticated using(exists(select 1 from public.posts where id=post_id and (author_id=auth.uid() or public.can_moderate())));
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('forum-media','forum-media',true,20971520,array['image/jpeg','image/png','image/webp','image/gif','audio/mpeg','audio/ogg','audio/wav','audio/mp4']) on conflict(id) do nothing;
drop policy if exists "forum upload" on storage.objects; drop policy if exists "forum read" on storage.objects; drop policy if exists "forum delete" on storage.objects; create policy "forum upload" on storage.objects for insert to authenticated with check(bucket_id='forum-media' and (storage.foldername(name))[1]=auth.uid()::text); create policy "forum read" on storage.objects for select using(bucket_id='forum-media'); create policy "forum delete" on storage.objects for delete to authenticated using(bucket_id='forum-media' and ((storage.foldername(name))[1]=auth.uid()::text or public.can_moderate()));
